/// <summary>
/// Client only. Invisible solid boxes in this game only, as an editor's author uses to keep players
/// off a cliff edge, close a gap with a floor or lay a ramp up to a door. A box blocks players,
/// horses and anything else the game's physics moves, and nothing draws it. The server does not
/// know about it, and no other player has it. A resource's boxes are taken away when it stops or
/// the world goes. World Architect's Collision mode is built on it. (Client only.)
/// </summary>
public static class Collision
{

    /// <summary>
    /// Adds a solid invisible box and returns it. The box has `id`, `valid`, `center`, `size` and
    /// `rotation`, and two methods: `set({ center, size, rotation })` moves, sizes or turns it in one
    /// go, leaving out what is undefined; `remove()` takes it away and is safe to repeat. Throws a
    /// TypeError for a missing center or size, a RangeError for a side outside 0.02 to 200 metres, a
    /// centre out of the world, or more than 1024 boxes in this game. (Client only.)
    /// </summary>
    /// <param name="box">{ center, size, rotation }: its middle (Vector3); its width, depth and height in metres along its own axes (Vector3); and optionally its turn, a quaternion or angles in degrees { x, y, z }, none by default.</param>
    /// <returns>{ readonly id: number; readonly valid: boolean; readonly center: Vector3; readonly size: Vector3; readonly rotation: Quaternion; set(pose: { center?: Vector3; size?: Vector3; rotation?: { x: number; y: number; z: number; w?: number } }): void; remove(): void }</returns>
    public static JsValue AddBox(object? box = null) => Sdk.Call<JsValue>("world", "Collision", "addBox", Sdk.Optional(box));

    /// <summary>
    /// Your resource's boxes that still stand. (Client only.)
