/// <summary>
/// Client only. Shapes and paints the level's ground in this game only, as an editor does under a
/// building it places: a flat pad, a hill, a hollow, a cobbled lane. The ground is solid at once
/// where it now lies. The server does not know about it, and no other player sees it. Every edit
/// can be undone, and a resource's edits are undone when it stops or the world goes. An edit
/// reaches at most 90 m from its middle; ground pushed beyond what its patch of terrain can hold
/// stops at that height. (Client only.)
/// </summary>
public static class Terrain
{

    /// <summary>
    /// Brings the ground in the circle to one height, fading into the ground around it. Throws a
    /// TypeError for a bad place, size or height, a RangeError for one out of the world or wider than
    /// 90 m. (Client only.)
    /// </summary>
    /// <param name="center">Its middle; z is not used.</param>
    /// <param name="radius">Metres of flat ground from the middle.</param>
    /// <param name="height">The height of the flat ground, in metres.</param>
    /// <param name="falloff">Optional: metres over which it fades into the ground around. The radius by default.</param>
    /// <returns>TerrainEdit</returns>
    public static JsValue Flatten(object? center, object? radius, object? height, object? falloff = null) => Sdk.Call<JsValue>("world", "Terrain", "flatten", center, radius, height, Sdk.Optional(falloff));

    /// <summary>
    /// Lifts the ground in the circle by an amount, or lowers it with a negative one, fading at the
    /// edge. (Client only.)
    /// </summary>
    /// <param name="center">Its middle; z is not used.</param>
    /// <param name="radius">Metres from the middle at full strength.</param>
    /// <param name="amount">Metres up, or down when negative.</param>
    /// <param name="falloff">Optional: metres over which it fades. The radius by default.</param>
    /// <returns>TerrainEdit</returns>
    public static JsValue Raise(object? center, object? radius, object? amount, object? falloff = null) => Sdk.Call<JsValue>("world", "Terrain", "raise", center, radius, amount, Sdk.Optional(falloff));

    /// <summary>
    /// Covers the ground in the circle with a material: its look, the sound of footsteps on it and the
    /// dust it raises. Full in the circle, blended into the ground around over the falloff (up to three
    /// materials mix on one metre). A World Architect custom map carries all of the materials
    /// everywhere. On a game level a name finds the level's own material of that kind (its
    /// cobblestones, sand or trampled soil), and a patch of terrain without it takes it in; a material
    /// the level does not have at all (such as gravel on one level) leaves the ground as it was. Roads
    /// lie over the ground and hide paint under them. Throws a TypeError for a bad place, size or
    /// material number, a RangeError for an unknown material name or a place out of the world or wider
    /// than 90 m. (Client only.)
    /// </summary>
    /// <param name="center">Its middle; z is not used.</param>
    /// <param name="radius">Metres from the middle fully covered.</param>
    /// <param name="material">A name: 'grass', 'meadow', 'pasture', 'trampled', 'soil', 'mud', 'stony_mud', 'sand', 'gravel', 'forest', 'forest_leaves', 'cobblestones', 'paving', 'cobblestones_grass' or 'river_shore'; or the level's surface type number (0 to 126).</param>
    /// <param name="falloff">Optional: metres over which it blends into the ground around. The radius by default.</param>
    /// <returns>TerrainEdit</returns>
    public static JsValue Paint(object? center, object? radius, object? material, object? falloff = null) => Sdk.Call<JsValue>("world", "Terrain", "paint", center, radius, material, Sdk.Optional(falloff));

    /// <summary>
    /// Takes the level's grass carpet away in the circle, in this game only: a yard, a threshing floor
    /// or the floor of a house stands bare. Trees, bushes and the ground itself stay. The grass comes
    /// back when the edit is undone or the resource stops. Throws a TypeError for a bad place or size,
    /// a RangeError for a radius of 0, more than 90 m or a place out of the world. (Client only.)
    /// </summary>
    /// <param name="center">Its middle; z is not used.</param>
    /// <param name="radius">Metres from the middle without grass.</param>
    /// <returns>TerrainEdit</returns>
    public static JsValue HideGrass(object? center, object? radius) => Sdk.Call<JsValue>("world", "Terrain", "hideGrass", center, radius);

    /// <summary>
    /// Closes the game's navmesh in a box, in this game only: the NPCs this game moves plan their paths
    /// around it, as around a wall (a house placed on a game map, a fenced yard). The level's own
    /// navigation is opened again when the edit is undone or the resource stops. A box is laid on the
    /// navmesh tiles there now and again every few seconds, as tiles load. Throws a TypeError for a bad
    /// place, a RangeError for a box wider than 180 m or out of the world. (Client only.)
    /// </summary>
    /// <param name="min">The box's lowest corner. Without z the box reaches far under the ground.</param>
    /// <param name="max">The box's highest corner. Without z the box reaches far over the ground.</param>
    /// <returns>TerrainEdit</returns>
    public static JsValue BlockNavmesh(object? min, object? max) => Sdk.Call<JsValue>("world", "Terrain", "blockNavmesh", min, max);

    /// <summary>
    /// The material names paint takes, each with the level's surface type number it stands for. (Client
    /// only.)
    /// </summary>
    /// <returns>object</returns>
    public static JsValue Materials() => Sdk.Call<JsValue>("world", "Terrain", "materials");

    /// <summary>
    /// Your resource's edits that are still in place, oldest first. (Client only.)
    /// </summary>
    /// <returns>TerrainEdit[]</returns>
    public static JsValue Edits() => Sdk.Call<JsValue>("world", "Terrain", "edits");
}

/// <summary>
/// Client only. Plants trees, bushes and the like in this game only, any kind of vegetation the
/// level has, as an editor does while its author works. A plant stands solid and bends in the wind
/// like the level's own. The server does not know about it, and no other player sees it. A
/// resource's plants are taken away when it stops or the world goes. (Client only.)
/// </summary>
public static class Vegetation
{

    /// <summary>
