/// <summary>
/// The stew pots on the game's fireplaces, with stock held by the server per dimension: the meal,
/// 'goulash', 'lentil' or 'soup', the meals left, whether eating is allowed, and any poison. A pot
/// is named by its fireplace's GUID. An untouched pot serves the level's meal, four of it, or none
/// if the level starts it empty. A pot is { guid, position, food, nutrition, poison, portions,
/// capacity, enabled, state, fireLit, dimension }. `state` is 'empty', 'half' or 'full'. `fireLit`
/// is the state set by setFire, or null while each player's game controls its own fire. Stock lasts
/// until the server stops. Calls made for a player return { ok, code }, with codes such as
/// unknownPot, tooFar (over 4 m), cannotAct, disabled, notEmpty and insufficientItems. (Server
/// only.)
/// </summary>
public static class CookPot
{

    /// <summary>
    /// The pots in a dimension: all catalogued pots in the shared one, or those used in another.
    /// (Server only.)
    /// </summary>
    /// <param name="dimension">Optional: the dimension.</param>
    /// <returns>object[]</returns>
    public static JsValue All(object? dimension = null) => Sdk.Call<JsValue>("world", "CookPot", "all", Sdk.Optional(dimension));

    /// <summary>
    /// One pot's stock, or null for an unknown GUID. (Server only.)
    /// </summary>
