    /// <summary>
    /// Adds meals, 0 to 1000 and by default 4, and clears the poison. (Server only.)
    /// </summary>
    /// <param name="guid">The fireplace's GUID.</param>
    /// <param name="portions">Meals to add.</param>
    /// <param name="dimension">Optional: the dimension.</param>
