    /// <param name="guid">The fireplace's GUID.</param>
    /// <param name="lit">true lights it, false puts it out, and null returns control.</param>
    /// <param name="dimension">Optional: the dimension.</param>
    /// <returns>boolean</returns>
    public static bool SetFire(object? guid, object? lit, object? dimension = null) => Sdk.Call<bool>("world", "CookPot", "setFire", guid, lit, Sdk.Optional(dimension));

    /// <summary>
    /// Allows or forbids eating from a pot. (Server only.)
    /// </summary>
    /// <param name="guid">The fireplace's GUID.</param>
    /// <param name="enabled">true or false.</param>
    /// <param name="dimension">Optional: the dimension.</param>
    /// <returns>boolean</returns>
    public static bool SetEnabled(object? guid, object? enabled, object? dimension = null) => Sdk.Call<bool>("world", "CookPot", "setEnabled", guid, enabled, Sdk.Optional(dimension));

    /// <summary>
    /// Sets how full a pot looks and how much it holds. (Server only.)
    /// </summary>
    /// <param name="guid">The fireplace's GUID.</param>
    /// <param name="state">'empty', 'half' or 'full'.</param>
    /// <param name="dimension">Optional: the dimension.</param>
    /// <returns>boolean</returns>
    public static bool SetState(object? guid, object? state, object? dimension = null) => Sdk.Call<bool>("world", "CookPot", "setState", guid, state, Sdk.Optional(dimension));

    /// <summary>
    /// Changes the meal a pot serves, and its look follows. (Server only.)
    /// </summary>
    /// <param name="guid">The fireplace's GUID.</param>
    /// <param name="food">'goulash', 'lentil' or 'soup'.</param>
    /// <param name="dimension">Optional: the dimension.</param>
    /// <returns>boolean</returns>
    public static bool SetFood(object? guid, object? food, object? dimension = null) => Sdk.Call<bool>("world", "CookPot", "setFood", guid, food, Sdk.Optional(dimension));

    /// <summary>
    /// The item GUIDs of poisons a pot accepts. (Server only.)
    /// </summary>
    /// <returns>string[]</returns>
    public static string[] Poisons() => Sdk.Call<string[]>("world", "CookPot", "poisons");

    /// <summary>
    /// Refills an empty pot from a player's inventory, using up the ingredients. (Server only.)
    /// </summary>
    /// <param name="player">The player, within 4 m of the pot.</param>
    /// <param name="guid">The fireplace's GUID.</param>
    /// <param name="recipe">{ food, portions (1 to 1000), ingredients: [{ item, amount }] }.</param>
    /// <returns>{ ok, code }</returns>
