/// <summary>
/// Herb picking and regrowth. Players pick the level's plants as in single player, but the server
/// decides. It checks that the player is within 5 m, the plants have not been picked in that
/// dimension, and the player is not picking too fast. A valid pick gives the herb and 5 Survival
/// XP, and hides the plants for everyone in the dimension. Plants grow back on the world clock, by
/// default in a fifth of the game's time. Nothing is saved, so a restart brings all plants back.
/// Events are gatheringHarvest, which can refuse, and gatheringHarvested. (Server only.)
/// </summary>
public static class Gathering
{

    /// <summary>
    /// The level's herbs available to pick within a sphere in a dimension, with no player needed
    /// nearby. Each has its kind, the herb it gives, and its position. Picked plants that have not
    /// grown back, removed plants, kinds turned off, and plants a resource placed are left out. Cost
    /// grows with the plants inside: on Kutnohorsko, a 50 m sphere takes about 0.2 ms, and a 500 m one,
    /// with 145,000 plants, about 100 ms. Invalid arguments throw. (Server only.)
    /// </summary>
    /// <param name="position">The centre, in world metres.</param>
    /// <param name="radius">Metres, 0 to 100000, inclusive and in three dimensions.</param>
    /// <param name="dimension">Optional: by default, the shared one. Pass player.dimension for a player's.</param>
    /// <returns>GatheringHerb[]</returns>
    public static JsValue HerbsWithin(object? position, object? radius, object? dimension = null) => Sdk.Call<JsValue>("world", "Gathering", "herbsWithin", position, radius, Sdk.Optional(dimension));

    /// <summary>
    /// Removes the level's herbs within a sphere in a dimension, including picked ones, until
    /// Gathering.respawn, regrowEverywhere, Area.regrowHerbs or a server restart. It gives no items, XP
    /// or harvest events. All games in the dimension hide them, including later joiners. Returns how
    /// many were not already removed, so repeating it returns 0. Invalid arguments throw before
    /// anything changes. (Server only.)
    /// </summary>
    /// <param name="position">The centre, in world metres.</param>
    /// <param name="radius">Metres, 0 to 100000, inclusive and in three dimensions.</param>
    /// <param name="dimension">Optional: by default, the shared one. Pass player.dimension for a player's.</param>
    /// <returns>number</returns>
    public static double ClearHerbs(object? position, object? radius, object? dimension = null) => Sdk.Call<double>("world", "Gathering", "clearHerbs", position, radius, Sdk.Optional(dimension));

    /// <summary>
    /// The bounds from setRegrowth, as { minHours, maxHours }, or null for the default. (Server only.)
    /// </summary>
    public static JsValue RegrowTime
    {
        get => Sdk.Get<JsValue>("world", "Gathering", "regrowTime");
    }

    /// <summary>
    /// Makes picked plants grow back after a random time between the bounds, in game hours, up to
    /// 87600. Returns false for invalid bounds. (Server only.)
    /// </summary>
    /// <param name="minHours">The shortest time.</param>
    /// <param name="maxHours">The longest time.</param>
    /// <returns>boolean</returns>
    public static bool SetRegrowth(object? minHours, object? maxHours) => Sdk.Call<bool>("world", "Gathering", "setRegrowth", minHours, maxHours);

    /// <summary>
    /// Returns to the default regrowth times. (Server only.)
    /// </summary>
    /// <returns>void</returns>
    public static void ResetRegrowth() => Sdk.Call("world", "Gathering", "resetRegrowth");

    /// <summary>
    /// Brings back picked and removed plants within a radius at once, including those with regrowth
    /// off. Returns how many picks and removals ended. Invalid arguments throw. (Server only.)
    /// </summary>
    /// <param name="position">The centre.</param>
    /// <param name="radius">Metres.</param>
    /// <param name="dimension">Optional: by default, the shared one.</param>
    /// <returns>number</returns>
    public static double Respawn(object? position, object? radius, object? dimension = null) => Sdk.Call<double>("world", "Gathering", "respawn", position, radius, Sdk.Optional(dimension));

    /// <summary>
    /// Brings back all picked and removed plants in a dimension at once. Returns how many picks and
    /// removals ended. (Server only.)
    /// </summary>
    /// <param name="dimension">Optional: by default, the shared one.</param>
    /// <returns>number</returns>
    public static double RegrowEverywhere(object? dimension = null) => Sdk.Call<double>("world", "Gathering", "regrowEverywhere", Sdk.Optional(dimension));

    /// <summary>
    /// Turns the world's natural plants of a kind on or off for all players, including later joiners,
    /// or all kinds if left out. Returns how many kinds changed. (Server only.)
    /// </summary>
    /// <param name="enabled">true or false.</param>
    /// <param name="kind">Optional: a plant kind's name or id.</param>
    public static JsValue SetNaturalSpawns(object? enabled, object? kind = null) => Sdk.Call<JsValue>("world", "Gathering", "setNaturalSpawns", enabled, Sdk.Optional(kind));

    /// <summary>
    /// The plant kinds now turned off. (Server only.)
    /// </summary>
    public static JsValue NaturalSpawnsOff() => Sdk.Call<JsValue>("world", "Gathering", "naturalSpawnsOff");
}

/// <summary>
/// Felling the level's trees, meaning meshes under objects/natural/vegetation/trees/ or added with
/// setSpecies. A blow counts when the player holds an axe, stands within reach and has not landed
/// one in the last swing time. After `hits` blows, the tree falls away from the chopper in the same
/// way on all screens. The standing tree and its collision are hidden for the dimension, and its
/// mesh falls as a prop, turned about its foot by the server along a gravity curve. Blows on the
/// trunk then cut it into `drops`, into the chopper's inventory or onto the ground. It grows back
/// after `regrowMinutes`, once no player is within `regrowClearance` metres. All of this is per
/// dimension and in memory, so a restart restores all trees, unless a script keeps state() and
/// passes it to restore(). Server events are playerTreeChop, playerTreeFell, playerTrunkChop and
/// playerTrunkCut, which can refuse, treeFelled, treeRegrow, which can refuse, and treeRegrown.
/// Client scripts of players in the dimension hear treeChop, treeFalling, treeFelled, trunkCut and
/// treeRegrown. (Server only.)
/// </summary>
public static class Trees
{

    /// <summary>
    /// Changes settings for all trees, leaving out others unchanged, and returns them all. They are
    /// `enabled`, default true; `hits`, default 8; `trunkHits`, default 6; `regrowMinutes`, real
    /// minutes, default 30; `regrowClearance`, default 10 m; `reach`, from the chopper's feet, default
    /// 3.5 m; `swingSeconds`, the shortest time between one player's blows, default 0.4; `height`,
    /// trunk length at scale 1, default 15 m; `trunkRadius`, default 0.35 m; `drops`, [{ item, amount
    /// }], default 2 bsmt_woodExotic; `dropTo`, 'inventory' or 'ground'; `stump`, a prop model left in
    /// place, or null; and `axes`, the item classes that chop, or null for all melee weapons named like
    /// an axe. Throws for an unknown setting or wrong value. (Server only.)
    /// </summary>
    /// <param name="settings">The settings to change.</param>
    /// <returns>TreeSettings</returns>
    public static JsValue Configure(object? settings) => Sdk.Call<JsValue>("world", "Trees", "configure", settings);

    /// <summary>
    /// A copy of the settings all trees use now. (Server only.)
    /// </summary>
    public static JsValue Settings
    {
        get => Sdk.Get<JsValue>("world", "Trees", "settings");
    }

    /// <summary>
    /// Settings for trees whose mesh path starts with `prefix`, in any case and with either slash, on
    /// top of configure's: `hits`, `trunkHits`, `regrowMinutes`, `height`, `trunkRadius`, `drops` and
    /// `stump`. A prefix outside objects/natural/vegetation/trees/ also makes those meshes trees, such
    /// as a resource's own. The last prefix set wins. (Server only.)
    /// </summary>
    /// <param name="prefix">A mesh path or its start.</param>
    /// <param name="settings">The species' settings.</param>
    /// <returns>boolean</returns>
    public static bool SetSpecies(object? prefix, object? settings) => Sdk.Call<bool>("world", "Trees", "setSpecies", prefix, settings);

    /// <summary>
    /// Whether a mesh path is a tree that can be felled. (Server only.)
    /// </summary>
    /// <param name="mesh">A mesh path, from WorldRayHit.levelObject.name.</param>
    /// <returns>boolean</returns>
    public static bool IsTree(object? mesh) => Sdk.Call<bool>("world", "Trees", "isTree", mesh);

    /// <summary>
    /// A tree being chopped, felled or cut, by its id, `&lt;mesh&gt;@&lt;x&gt;,&lt;y&gt;,&lt;z&gt;`.
    /// Null for a tree nobody has touched, which stands as the level has it. (Server only.)
    /// </summary>
    /// <param name="id">The tree's id.</param>
    /// <param name="dimension">Optional: by default, the shared one.</param>
    /// <returns>Tree | null</returns>
    public static JsValue Get(object? id, object? dimension = null) => Sdk.Call<JsValue>("world", "Trees", "get", id, Sdk.Optional(dimension));

