    /// <param name="first">The first player's network id.</param>
    /// <param name="second">The second player's network id.</param>
    /// <param name="options">`targetScore`, default 2000, up to 100000; `firstName` and `secondName`, shown in each game, up to 64 bytes; `firstDice` and `secondDice`, six dice kind names each; `firstBadge` and `secondBadge`, badge names.</param>
    /// <returns>number</returns>
