    /// <summary>
    /// Starts a match between a player and an opponent run by the server, at the table where the player
    /// stands or sits. The server makes each throw and plays the opponent's turns at the chosen
    /// difficulty, and the player's game shows them like another player's. The body is the given Npc,
    /// or a stand-in the server seats on the free chair. diceMatchStart, the turn events and
    /// diceMatchEnd follow as for two players, with null for the opponent's seat. Returns the match id,
    /// and throws if the player is not at a table, is already playing, or an option is unusable.
    /// (Server only.)
    /// </summary>
    /// <param name="player">The player, or their network id.</param>
    /// <param name="options">`difficulty`, 'easy', 'normal' (default), 'hard' or a skill from 0 to 100, which sets how much it risks and how often an easy one keeps fewer dice than it could; `npc`, an Npc to play it, otherwise a stand-in; `npcName`, by default the Npc's name or 'Opponent'; `targetScore`, default 2000; `playerName`; `playerDice` and `npcDice`, six dice kind names each; `playerBadge` and `npcBadge`, badge names, where the NPC plays only passive ones.</param>
    /// <returns>number</returns>
    public static double StartAgainstNpc(object? player, object? options = null) => Sdk.Call<double>("world", "Dice", "startAgainstNpc", player, Sdk.Optional(options));

