    public static JsValue BadgesOf(object? match) => Sdk.Call<JsValue>("world", "Dice", "badgesOf", match);

    /// <summary>
    /// Each seat's six dice kinds in a match, with null for plain dice. (Server only.)
    /// </summary>
    /// <param name="match"></param>
    /// <returns>(string[] | null)[] | null</returns>
    public static JsValue DiceOf(object? match) => Sdk.Call<JsValue>("world", "Dice", "diceOf", match);

    /// <summary>
    /// Gives a player who is not in the match a camera above its dice, so they can read them: it moves
    /// to each throw and looks straight down. Their body stays where it is, and they see the dice from
    /// any distance. Returns false when the match does not exist, the player is not connected, or the
