    /// <returns>boolean</returns>
    public static bool ClearWaypoint() => Sdk.Call<bool>("world", "WorldMap", "clearWaypoint");

    /// <summary>
    /// Removes all map fog in the level for this player, leaving discovery alone. By default a KCDS
    /// server already lifts fog as the world loads, so this is for servers keeping the fog. A level
    /// load brings fog back. Returns false before the level is up. (Client only.)
    /// </summary>
    /// <returns>boolean</returns>
    public static bool ClearAllFog() => Sdk.Call<bool>("world", "WorldMap", "clearAllFog");

    /// <summary>
    /// Discovers a place on this player's map with no notification, XP or game trigger. Sessions start
    /// with an unexplored map, so use it to restore a saved character's discoveries after loading. A
    /// point of interest fires poiDiscovered, while a location such as a town or district fires
    /// nothing. Returns true if the id belongs to the current level, even if already discovered, and
    /// false for other ids or before the level has loaded. Throws a TypeError for anything except a
    /// LocationId. (Client only.)
    /// </summary>
    /// <param name="id">A point of interest or location from poiDiscovered or locationDiscovered: { data1, data2, data3, data4 }, where data4 is a Uint8Array of eight bytes.</param>
    /// <returns>boolean</returns>
    public static bool Discover(object? id) => Sdk.Call<bool>("world", "WorldMap", "discover", id);

    /// <summary>
    /// Removes fog around a point for this player with the radius of visiting it, without discovering
    /// anything. Use it to restore a saved character's explored areas after loading. It only has an
    /// effect when the server's revealMap is off, and fog returns on the next level load. Returns false
    /// before the level is up, and throws a TypeError for a position without finite x and y. (Client
    /// only.)
    /// </summary>
    /// <param name="position">A world position; z is ignored.</param>
    /// <returns>boolean</returns>
    public static bool ClearFog(object? position) => Sdk.Call<bool>("world", "WorldMap", "clearFog", position);
}

/// <summary>
/// Client only. Read-only information about the local player's fast travel on the map. (Client
/// only.)
/// </summary>
public static class Travel
{

    /// <summary>
    /// Whether the player is fast travelling now. (Client only.)
    /// </summary>
    public static bool Active
    {
        get => Sdk.Get<bool>("world", "Travel", "active");
    }

    /// <summary>
    /// The location of the travel marker, or (0, 0, 0) when not travelling. (Client only.)
    /// </summary>
    public static Kcds.Math.Vector3 Position
    {
        get => Sdk.Get<Kcds.Math.Vector3>("world", "Travel", "position");
    }

    /// <summary>
    /// Asks the game whether fast travel could begin now, without starting it or considering a
    /// destination. The answer refreshes about four times per second. The codes are the map's own
    /// reasons: 0 yes, 1 not now, including during a journey, 2 not from here, such as inside a
    /// building, 3 in combat, 4 hungry, 5 poisoned, 6 bleeding, 7 time is paused, 8 trespassing, 9 too
    /// tired, 10 overloaded, 11 tense circumstances. (Client only.)
    /// </summary>
    /// <returns>number | null</returns>
    public static double? CanStart() => Sdk.Call<double?>("world", "Travel", "canStart");
}

/// <summary>
/// Client only. Debug drawings that only this player sees. Each has an id you choose, and setting
/// it again replaces it. A resource can have up to 128. Colours are 0xAARRGGBB numbers. Drawings
/// end when your resource stops, on disconnecting, and on another level. To draw for chosen
/// players, use the server's Gizmo. (Client only.)
/// </summary>
public static class Gizmos
{

    /// <summary>
    /// Draws a shape, replacing any drawing with this id. (Client only.)
    /// </summary>
    /// <param name="id">Your name for it, up to 128 bytes.</param>
    /// <param name="primitive">{ type, ... }: 'line' { from, to }; 'arrow' { from, to, headLength }; 'box' { position, rotation, min, max }; 'sphere' { position, radius }; 'shape' { points, height }, a polygon area; 'capsule', 'cone' or 'cylinder' { from, to, radius, segments }; 'circle' { position, normal, radius, segments }; 'grid' { position, normal, size, divisions }; 'axes' { position, rotation, size }; 'polyline' { points, closed }; 'mesh' { points, indices, wireframe }. A mesh's filled face shows only from the side its corners run clockwise seen from; give a face both ways round (a, b, c and a, c, b) to see it from both sides.</param>
    /// <param name="style">Optional: `color`, green by default; `fillColor`, for solid shapes only; `width`, 0.5 to 8; `depthTest`, true by default, which hides it behind walls; `durationMs`, where 0 lasts until removed.</param>
    /// <returns>void</returns>
    public static void Set(object? id, object? primitive, object? style = null) => Sdk.Call("world", "Gizmos", "set", id, primitive, Sdk.Optional(style));

    /// <summary>
    /// Moves and turns a whole drawing. (Client only.)
    /// </summary>
    /// <param name="id">The drawing's id.</param>
    /// <param name="position">The offset.</param>
    /// <param name="rotation">The rotation.</param>
    /// <returns>boolean</returns>
    public static bool SetTransform(object? id, object? position, object? rotation) => Sdk.Call<bool>("world", "Gizmos", "setTransform", id, position, rotation);

    /// <summary>
    /// Removes a drawing. (Client only.)
    /// </summary>
    /// <param name="id">The drawing's id.</param>
    /// <returns>boolean</returns>
    public static bool Remove(object? id) => Sdk.Call<bool>("world", "Gizmos", "remove", id);

    /// <summary>
    /// Removes all of your resource's drawings. (Client only.)
    /// </summary>
    /// <returns>void</returns>
    public static void Clear() => Sdk.Call("world", "Gizmos", "clear");
}

/// <summary>
/// Takes pictures of the world from any camera on this machine, without the player seeing that
/// view. A picture is the frame as the game renders it, including the HUD as the player has it, but
/// not KCDS's chat or nameplates. For about a tenth of a second while it is taken, the player keeps
/// seeing the previous frame. (Client only.)
/// </summary>
public static class Render
{

    /// <summary>
    /// Takes a picture from a camera pose, given as for Camera.startShot. Pictures are taken one at a
    /// time, and others wait. Rejects with 'Render.view failed: &lt;reason&gt;' if the world changed,
    /// the view could not be made, or no frame arrived within 15 seconds. (Client only.)
    /// </summary>
    /// <param name="options">`position`; then `rotation` (a Quaternion) or `lookAt` (a point) with `roll` (-180 to 180 degrees); `fov` (5 to 150 degrees, where 0 or none keeps the game's value); `width` (16 to 7680, the PNG's width, with height following the frame's aspect; none uses the window's size); `ui` (false leaves the native screens of resources, NativeUI.createScreen, out of the picture; they are hidden only behind the frame the player keeps seeing, so the player never sees them go; true by default).</param>
    /// <returns>Promise&lt;{ png, width, height }&gt;: png is a data URL (data:image/png;base64,...).</returns>
    public static Task<JsValue> View(object? options = null) => Sdk.Call<Task<JsValue>>("world", "Render", "view", Sdk.Optional(options));
}

/// <summary>
/// The game's sound triggers. In a client script it plays, stops and adjusts them on this machine
/// only, with nothing sent to others: each call returns whether the game accepted it, false before
/// a world has loaded, for a name the game's audio data does not have, and for an entity that is
/// not there. In a server script, playAt and playFrom play one for every player near a point or a
/// body, and list names the game's triggers. The game's cinematic triggers (cin_*) play without an
/// error outside their scene but are not heard, because their sound bank loads only with the scene.
/// </summary>
public static class Audio
{

    /// <summary>
    /// Plays a trigger as a free sound at a point for every player within `range` of it, in its
    /// dimension, whose client scripts run. The sound is told once: a player who comes near later does
    /// not hear it. Returns whether any player was told.
    /// </summary>
    /// <param name="trigger">The trigger name.</param>
    /// <param name="position">A Vector3.</param>
    /// <param name="options">Optional: `range`, metres, more than 0 and at most 200, default 30; `dimension`, by default the shared one.</param>
    /// <returns>boolean</returns>
    public static bool PlayAt(object? trigger, object? position, object? options = null) => Sdk.Call<bool>("world", "Audio", "playAt", trigger, position, Sdk.Optional(options));

    /// <summary>
    /// Plays a trigger from an entity's body, so it moves with it, for every player within `range` of
    /// it, in its dimension, whose client scripts run. A game without that body plays it where the
    /// entity was. Returns whether any player was told.
    /// </summary>
    /// <param name="trigger">The trigger name.</param>
    /// <param name="entity">A Player, an Npc, a Horse or its network id.</param>
    /// <param name="options">Optional: `range`, metres, more than 0 and at most 200, default 30.</param>
    /// <returns>boolean</returns>
    public static bool PlayFrom(object? trigger, object? entity, object? options = null) => Sdk.Call<bool>("world", "Audio", "playFrom", trigger, entity, Sdk.Optional(options));

    /// <summary>
    /// Server only. The game's sound trigger names (from its Libs/GameAudio files), sorted, optionally
    /// only those starting with `prefix`, as Vfx.list names effects. The cinematics' triggers (cin_*)
    /// are left out: outside their scene they are not heard. (Server only.)
    /// </summary>
    /// <param name="prefix">Optional: only names starting with it, such as 'a_o_bell'.</param>
    /// <returns>string[]</returns>
    public static string[] List(object? prefix = null) => Sdk.Call<string[]>("world", "Audio", "list", Sdk.Optional(prefix));

    /// <summary>
    /// Plays a trigger at the local player. (Client only.)
    /// </summary>
    /// <param name="trigger">The trigger name.</param>
    /// <returns>boolean</returns>
    public static bool Play(object? trigger) => Sdk.Call<bool>("world", "Audio", "play", trigger);

    /// <summary>
    /// Plays a resource's .ogg file on an entity through one of the game's voice events. (Client only.)
    /// </summary>
    /// <param name="file">A game path from the root, with forward slashes and no drive or parent folder.</param>
    /// <param name="entityId">The entity it comes from.</param>
    /// <param name="purpose">How it sounds: 'inner' for an inner voice; '10', '20', '35', '50' (default), '100' or '200', heard up to that many metres; 'sfp_dialog', 'sfp_cutscene' or 'sfp_music'.</param>
    /// <returns>boolean</returns>
    public static bool PlayFile(object? file, object? entityId, object? purpose = null) => Sdk.Call<bool>("world", "Audio", "playFile", file, entityId, Sdk.Optional(purpose));

    /// <summary>
    /// Stops one trigger playing on an entity. (Client only.)
    /// </summary>
    /// <param name="trigger">The trigger name.</param>
    /// <param name="entityId">The entity.</param>
    /// <returns>boolean</returns>
    public static bool StopFrom(object? trigger, object? entityId) => Sdk.Call<bool>("world", "Audio", "stopFrom", trigger, entityId);

    /// <summary>
    /// Stops all sounds on an entity, including the game's own. (Client only.)
    /// </summary>
    /// <param name="entityId">The entity.</param>
    /// <returns>boolean</returns>
    public static bool SilenceEntity(object? entityId) => Sdk.Call<bool>("world", "Audio", "silenceEntity", entityId);

    /// <summary>
    /// Sets one of the game's audio parameters (an RTPC) on an entity. (Client only.)
    /// </summary>
    /// <param name="entityId">The entity.</param>
    /// <param name="parameter">The parameter's name.</param>
    /// <param name="value">A number.</param>
    /// <returns>boolean</returns>
    public static bool SetSoundParameter(object? entityId, object? parameter, object? value) => Sdk.Call<bool>("world", "Audio", "setSoundParameter", entityId, parameter, value);

    /// <summary>
    /// Sets one of the game's audio switches on an entity. (Client only.)
    /// </summary>
    /// <param name="entityId">The entity.</param>
    /// <param name="switchName">The switch.</param>
    /// <param name="state">The state to set.</param>
    /// <returns>boolean</returns>
    public static bool SetSoundSwitch(object? entityId, object? switchName, object? state) => Sdk.Call<bool>("world", "Audio", "setSoundSwitch", entityId, switchName, state);

    /// <summary>
    /// Keeps a trigger playing at a point in the world until stopLoop, for an ambience, a fire or bees
    /// that should go on. Returns the loop's number, or 0 when the game did not play it. Leaving the
    /// world stops every kept sound. (Client only.)
    /// </summary>
    /// <param name="trigger">The trigger name, such as one of the game's world loops (a_l_village_amb01).</param>
    /// <param name="position">A Vector3.</param>
    /// <returns>number</returns>
    public static double LoopAt(object? trigger, object? position) => Sdk.Call<double>("world", "Audio", "loopAt", trigger, position);

    /// <summary>
    /// Stops a sound loopAt keeps playing. Returns false for a number that is not playing. (Client
    /// only.)
    /// </summary>
    /// <param name="loop">The number loopAt returned.</param>
    /// <returns>boolean</returns>
    public static bool StopLoop(object? loop) => Sdk.Call<bool>("world", "Audio", "stopLoop", loop);

    /// <summary>
    /// Whether the game's audio data has the trigger. (Client only.)
    /// </summary>
    /// <param name="trigger">The trigger name.</param>
    /// <returns>boolean</returns>
    public static bool TriggerExists(object? trigger) => Sdk.Call<bool>("world", "Audio", "triggerExists", trigger);
}
